@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@using sv_1b28c1fc972f4635aeafa88c3e184648.Models
@using sv_1b28c1fc972f4635aeafa88c3e184648.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Nav

<PageTitle>Recipes</PageTitle>

<h1>Recipes for Cuisine @CuisineId</h1>

@if (isRefreshing && recipes is not null)
{
    <div class="alert alert-info py-1 px-2 d-inline-block" role="status">
        <span class="spinner-border spinner-border-sm me-1" aria-hidden="true"></span>
        Refreshing&hellip;
    </div>
}

@if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-1">@errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (recipes is null)
{
    <p role="status">
        <span class="spinner-border spinner-border-sm me-1" aria-hidden="true"></span>
        Loading recipes&hellip;
    </p>
}

@if (recipes is not null)
{
    var sorted = GetSortedRecipes();
    <div class="row row-cols-1 row-cols-md-3 g-3 mt-2">
        @foreach (var recipe in sorted)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-body-secondary">
                        Prep: @recipe.PrepTimeMinutes min
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? recipes;
    private string? errorMessage;
    private bool isRefreshing;

    private int loadedCuisineId;
    private CancellationTokenSource? loadCts;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload when the cuisine actually changes, not on sort changes.
        if (CuisineId == loadedCuisineId && recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load for the previous cuisine.
        await CancelPendingLoadAsync();

        loadedCuisineId = CuisineId;
        errorMessage = null;
        isRefreshing = recipes is not null;

        if (!isRefreshing)
        {
            // First load — recipes stays null so the loading placeholder shows.
            StateHasChanged();
        }

        var cts = new CancellationTokenSource();
        loadCts = cts;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // Guard against a stale callback if cancellation raced.
            if (cts.Token.IsCancellationRequested)
            {
                return;
            }

            recipes = result;
            isRefreshing = false;
            errorMessage = null;
        }
        catch (OperationCanceledException)
        {
            // Load was intentionally cancelled — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            isRefreshing = false;
            errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            isRefreshing = false;
            errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (recipes is null)
        {
            return new List<Recipe>();
        }

        return string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : recipes.OrderByDescending(r => r.Id).ToList();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (loadCts is not null)
        {
            await loadCts.CancelAsync();
            loadCts.Dispose();
            loadCts = null;
        }
    }

    public void Dispose()
    {
        loadCts?.Cancel();
        loadCts?.Dispose();
        loadCts = null;
    }
}

